TWComponent.script:
//tw.local.odcRequest = {};
//tw.local.odcRequest.BasicDetails ={};
tw.local.odcRequest.BasicDetails.Invoice = new tw.object.listOf.Invoice();

if(tw.local.sqlResults.listLength > 0)
{
	for(var i =0; i<tw.local.sqlResults[0].rows.listLength ; i++)
	{
		tw.local.odcRequest.BasicDetails.Invoice[i]    			 = new tw.object.Invoice();
		tw.local.odcRequest.BasicDetails.Invoice[i].invoiceDate      = tw.local.sqlResults[0].rows[i].data[1];
		tw.local.odcRequest.BasicDetails.Invoice[i].invoiceNo        = tw.local.sqlResults[0].rows[i].data[0];
	}

}

tw.local.sql = "SELECT INVOICENO, INVOICEDATE, REQUESRID, ID FROM "+tw.env.LKP_DB_Schema+".odc_invoice where requesrid = ? ";

tw.local.sqlParameters = new tw.object.listOf.SQLParameter();
tw.local.sqlParameters[0] =  new tw.object.SQLParameter();
tw.local.sqlParameters[0].value = tw.local.requestId;

